  'Exodus 22':{summary:"The preceding judgments address bodily injury, servitude and liability.",links:["Exodus 21:36"]},
  'Exodus 23':{summary:"Israel has received judgments concerning property and vulnerable members of society.",links:["Exodus 22:22"]},
  'Exodus 24':{summary:"God has delivered covenant judgments and instructions concerning Israel's conduct.",links:["Exodus 23:33"]},
  'Exodus 25':{summary:"The covenant has been ratified and Moses has ascended the mountain.",links:["Exodus 24:18"]},
  'Exodus 26':{summary:"Instructions have been given for the sanctuary's primary furnishings.",links:["Exodus 25:40"]},
