  'Exodus 35':{summary:"The covenant has been renewed and Moses returns with the tablets.",links:["Exodus 34:29"]},
  'Exodus 36':{summary:"The people have offered materials and skilled workers have been appointed.",links:["Exodus 35:35"]},
  'Exodus 37':{summary:"The skilled workers have constructed the sanctuary's structural components.",links:["Exodus 36:38"]},
  'Exodus 38':{summary:"The sanctuary furnishings have been produced according to the instructions.",links:["Exodus 37:29"]},
  'Exodus 39':{summary:"The structure and furnishings have been constructed, and the materials have been accounted for.",links:["Exodus 38:21"]},
  'Exodus 40':{summary:"The completed work has been inspected and accepted by Moses.",links:["Exodus 39:43"]},
  'Genesis 21':{summary:"Isaac's promised birth follows the restoration of Abimelech's household.",links:["Genesis 20:17"]},
  'Genesis 22':{summary:"Isaac has been born and Abraham has established a treaty at Beersheba.",links:["Genesis 21:33"]},
